function activePromotionQuote(items=cart, code=couponCode) {
  const subtotal=items.reduce((sum,item)=>{const p=products.find(x=>x.id===item.productId)||item;return sum+Number(p.price||0)*Number(item.qty||0);},0);
  const itemCount=items.reduce((sum,item)=>sum+Number(item.qty||0),0);
  const today=new Date().toLocaleDateString('en-CA'), entered=String(code||'').trim().toUpperCase();
  let best=null;
  for(const p of promotions){if(!p.enabled||(p.starts&&today<p.starts)||(p.ends&&today>p.ends))continue;if(p.code&&p.code!==entered)continue;if(!p.code&&entered)continue;if(itemCount<Number(p.minItems||0)||subtotal<Number(p.minTotal||0))continue;const discount=p.type==='amount'?Math.min(subtotal,Number(p.value||0)):Math.round(subtotal*Math.min(100,Number(p.value||0))/100);const priority=((p.dayType==='holiday'||p.holiday)?100:0)+(Number(p.minTotal||0)>0?20:0)+(Number(p.minItems||0)>0?10:0);if(discount>0&&(!best||priority>best.priority||(priority===best.priority&&discount>best.discount)))best={...p,discount,priority};}
  const discount=best?.discount||0;return {subtotal,discount,total:Math.max(0,subtotal-discount),promotion:best};
}
