const displayCategory = value => String(value || 'Khác').split('>>').map(x=>x.trim()).filter(Boolean).join(' / ') || 'Khác';
const labelForCategory = category => category === 'all' ? 'Tất cả sản phẩm' : displayCategory(category);
const productBatchSize=()=>window.matchMedia('(max-width:800px)').matches?24:80;
function resetProductLimit(){productVisibleLimit=productBatchSize();}
function routeCategoryFromUrl(){return new URL(location.href).searchParams.get('category') || 'all';}
function urlForCategory(category){
  const url=new URL(location.href);
  if(category&&category!=='all'){url.searchParams.set('category',category);url.hash='products';}
  else{url.searchParams.delete('category');if(url.hash==='#products')url.hash='top';}
  return url;
}
function applyShopRoute(category,{push=false,replace=false,scroll=false}={}){
  currentCategory=category||'all';
  resetProductLimit();
  renderCategories();
  renderProducts();
  const url=urlForCategory(currentCategory);
  if(push&&url.href!==location.href) history.pushState({category:currentCategory},'',url);
  if(replace&&url.href!==location.href) history.replaceState({category:currentCategory},'',url);
  if(scroll){
    if(currentCategory==='all') window.scrollTo({top:0,behavior:'smooth'});
    else $('products')?.scrollIntoView({behavior:'smooth'});
  }
}
function productCard(p,index=0) { const images=(Array.isArray(p.images)&&p.images.length?p.images:[p.image]).filter(Boolean); const image = safeImage(images[0]); const sold = Number(p.sold || 0); const out = Number(p.stock || 0) <= 0; const promo=activePromotionQuote([{productId:p.id,qty:1,name:p.name,price:p.price}]).promotion; const gallery=images.slice(1,4).map(src=>safeImage(src)).filter(Boolean).map(src=>`<img src="${src}" alt="" />`).join(''); return `<article class="product-card reveal" style="--d:${Math.min(index,10)*35}ms"><div class="product-img">${image ? `<img src="${image}" alt="${escapeHTML(p.name)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="product-placeholder" hidden>✳</span>` : '<span class="product-placeholder">✳</span>'}${out ? '<span class="badge soldout">Hết hàng</span>' : promo ? `<span class="badge promo-badge">${escapeHTML(promo.name)}</span>` : p.isCombo ? '<span class="badge combo-badge">Combo</span>' : sold > 0 ? '<span class="badge">Bán chạy</span>' : ''}${gallery?`<div class="product-gallery">${gallery}</div>`:''}</div><div class="product-body"><div class="product-name">${escapeHTML(p.name)}</div><div class="price">${money(p.price)}</div><div class="stock">${out ? 'Tạm hết hàng' : p.isCombo ? `Còn ${Number(p.stock)||0} combo có thể bán` : `Còn ${Number(p.stock) || 0} sản phẩm`}</div><label class="product-quantity">Số lượng<input type="number" min="1" max="${Math.min(Number(p.stock)||1,1000)}" step="1" inputmode="numeric" value="1" aria-label="Số lượng ${escapeHTML(p.name)}" data-add-qty ${out ? 'disabled' : ''} /></label><button type="button" data-add="${escapeHTML(p.id)}" ${out ? 'disabled' : ''}>${out ? 'Hết hàng' : 'Thêm vào giỏ'}</button></div></article>`; }
function searchText(p){return `${p.name} ${p.category} ${p.description || ''} ${p.externalCode || ''} ${p.barcode || ''} ${Object.values(p.attributes || {}).join(' ')}`.toLocaleLowerCase('vi');}
function renderProducts() { if(!productVisibleLimit)resetProductLimit(); const keyword = $('searchInput').value.toLocaleLowerCase('vi').trim(), minPrice=Number($('minPriceFilter')?.value||0), maxPrice=Number($('maxPriceFilter')?.value||0), inStockOnly=!!$('inStockFilter')?.checked; const list = products.filter(p => searchText(p).includes(keyword) && (currentCategory === 'all' || p.category === currentCategory) && (!minPrice||Number(p.price||0)>=minPrice) && (!maxPrice||Number(p.price||0)<=maxPrice) && (!inStockOnly||Number(p.stock||0)>0)); const sort = $('sortSelect').value; if (sort === 'price-asc') list.sort((a,b) => Number(a.price)-Number(b.price)); if (sort === 'price-desc') list.sort((a,b) => Number(b.price)-Number(a.price)); const visible=list.slice(0,productVisibleLimit); $('productTotal').textContent = list.length>visible.length ? `${visible.length}/${list.length} sản phẩm` : `${list.length} sản phẩm`; $('filterLabel').textContent = labelForCategory(currentCategory); $('productGrid').innerHTML = visible.map((p,i)=>productCard(p,i)).join('') + (list.length>visible.length?`<div class="load-more-wrap"><button class="secondary-btn" data-load-more-products type="button">Xem thêm ${Math.min(productBatchSize(),list.length-visible.length)} sản phẩm</button></div>`:'') || `<div class="state-card reveal"><b>Chưa tìm thấy sản phẩm phù hợp.</b><p>Thử từ khóa khác hoặc xem tất cả danh mục.</p><button class="secondary-btn" data-reset type="button">Xem tất cả</button></div>`; const best = [...products].filter(p => Number(p.sold || 0) > 0 && Number(p.stock || 0) > 0).sort((a,b) => Number(b.sold || 0)-Number(a.sold || 0)).slice(0,4); $('bestSellers').classList.toggle('hidden', !best.length); $('bestGrid').innerHTML = best.map((p,i)=>productCard(p,i)).join(''); }
function renderSearchSuggestions(){const box=$('searchSuggest'),input=$('searchInput');if(!box||!input)return;const keyword=input.value.toLocaleLowerCase('vi').trim();if(keyword.length<2){box.classList.add('hidden');input.setAttribute('aria-expanded','false');box.innerHTML='';return;}const terms=keyword.split(/\s+/).filter(Boolean);const matches=products.map(p=>{const text=searchText(p);const score=terms.reduce((s,t)=>s+(text.includes(t)?1:0),0)+(p.name.toLocaleLowerCase('vi').includes(keyword)?2:0);return {p,score};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||Number(b.p.stock||0)-Number(a.p.stock||0)).slice(0,8).map(x=>x.p);input.setAttribute('aria-expanded',matches.length?'true':'false');box.classList.toggle('hidden',!matches.length);box.innerHTML=matches.map(p=>{const img=safeImage((Array.isArray(p.images)&&p.images[0])||p.image);const out=Number(p.stock||0)<=0;return `<button type="button" class="search-item" data-search-pick="${escapeHTML(p.id)}" role="option">${img?`<img src="${img}" alt="" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="search-thumb-fallback" hidden>✳</span>`:'<span class="search-thumb-fallback">✳</span>'}<span class="search-text"><b>${escapeHTML(p.name)}</b><small>${escapeHTML(displayCategory(p.category))} · ${money(p.price)} · ${out?'Hết hàng':`Còn ${Number(p.stock)||0}`}</small></span></button>`;}).join('');}
function chooseSearchSuggestion(id){const p=products.find(x=>x.id===id);if(!p)return;$('searchInput').value=p.name;currentCategory='all';renderCategories();renderProducts();$('searchSuggest')?.classList.add('hidden');$('searchInput')?.setAttribute('aria-expanded','false');$('products').scrollIntoView({behavior:'smooth'});}
function saveCart() { localStorage.setItem('cart', JSON.stringify(cart)); renderCart(); }
function renderCart() { $('cartCount').textContent = cart.reduce((sum,i) => sum + i.qty,0); $('cartItems').innerHTML = cart.map(item => { const p = products.find(x => x.id === item.productId) || item; const image = safeImage(p.image); return `<div class="cart-item">${image ? `<img class="cart-thumb" src="${image}" alt="" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="cart-thumb cart-thumb-fallback" hidden>✳</span>` : '<span class="cart-thumb cart-thumb-fallback">✳</span>'}<div><b>${escapeHTML(p.name)}</b><div>${money(p.price)} × ${item.qty}</div><div class="qty"><label>Số lượng <input type="number" min="1" max="${Math.min(Number(p.stock ?? 1000),1000)}" step="1" inputmode="numeric" value="${item.qty}" data-cart-qty="${escapeHTML(item.productId)}" aria-label="Số lượng ${escapeHTML(p.name)}" /></label><button type="button" data-remove="${escapeHTML(item.productId)}">Xóa</button></div></div><span class="cart-item-price">${money(Number(p.price || 0)*item.qty)}</span></div>`; }).join('') || '<div class="state-card"><b>Giỏ hàng đang trống.</b><p>Hãy chọn một món đồ cho bữa tiệc nhé.</p></div>'; const q=activePromotionQuote(); $('cartTotal').textContent = money(q.total); $('checkoutTotal').textContent = money(q.total); const note=$('discountLine'); if(note) note.innerHTML=q.discount?`Ưu đãi ${escapeHTML(q.promotion.name)}: -${money(q.discount)}`:''; const input=$('couponCode'); if(input&&input.value!==couponCode)input.value=couponCode; $('goCheckoutBtn').disabled = !cart.length; }
function addToCart(id, quantity = 1) {
  const p=products.find(x=>x.id===id); const existing=cart.find(x=>x.productId===id);
  if(!Number.isSafeInteger(quantity)||quantity<1) return notify('Nhập số lượng nguyên từ 1.',true);
  if(!p || quantity+(existing?.qty || 0)>Math.min(p.stock,1000)) return notify('Số lượng vượt tồn kho hoặc giới hạn 1.000 mỗi sản phẩm.',true);
  if(existing) existing.qty+=quantity; else cart.push({productId:id,qty:quantity,name:p.name,price:p.price});
  saveCart(); $('cartBtn').classList.remove('cart-pop'); void $('cartBtn').offsetWidth; $('cartBtn').classList.add('cart-pop'); openDrawer(); notify('Đã thêm vào giỏ hàng.');
}
function setCartQuantity(input) {
  const item=cart.find(i=>i.productId===input.dataset.cartQty); if(!item) return;
  const product=products.find(p=>p.id===item.productId); const qty=Number(input.value);
  if(!Number.isSafeInteger(qty)||qty<1||!product||qty>Math.min(product.stock,1000)) { input.value=item.qty; return notify('Nhập số lượng từ 1 đến số hàng còn trong kho (tối đa 1.000).',true); }
  item.qty=qty; saveCart();
}
function closeLayers() { $('cartPanel').classList.remove('open'); $('cartPanel').setAttribute('aria-hidden','true'); ['authModal','checkoutModal','myOrdersModal'].forEach(id => $(id).classList.add('hidden')); $('overlay').classList.add('hidden'); document.body.classList.remove('dialog-open'); }
