async function loadProducts() { $('productGrid').innerHTML=skeletonCards(); [products,categories] = await Promise.all([api('/api/products'),api('/api/categories')]); applyShopRoute(routeCategoryFromUrl(),{replace:true,scroll:routeCategoryFromUrl()!=='all'}); renderCart(); renderAdminProducts(); }
async function checkout() {
  if (busy) return;
  if (!cart.length) return notify('Giỏ hàng trống.',true);
  const customer = {name:$('customerName').value.trim(),phone:$('customerPhone').value.trim(),address:$('customerAddress').value.trim()};
  if (!customer.name || !/^(?:\+?84|0)\d{9,10}$/.test(customer.phone) || !customer.address) return notify('Nhập đủ họ tên, số điện thoại hợp lệ và địa chỉ.',true);
  const paymentMethod=$('paymentMethod').value;
  busy=true; $('checkoutBtn').disabled=true; $('checkoutBtn').textContent='Đang tạo đơn...';
  try {
    const order=await api('/api/orders',{method:'POST',body:JSON.stringify({items:cart,customer,paymentMethod,couponCode})});
    cart=[]; saveCart();
    try { await loadProducts(); } catch { notify('Đã tạo đơn; chưa tải lại được danh sách sản phẩm.',true); }
    $('checkoutForm').classList.add('hidden'); $('qrBox').classList.remove('hidden');
    viewedOrderId=order.id;
    renderPayment(order);
    notify('Đã tạo đơn hàng.');
  } catch(err) { notify(err.message,true); }
  finally { busy=false; $('checkoutBtn').disabled=false; $('checkoutBtn').textContent='Đặt hàng và lấy mã QR'; }
}
function renderAdminProducts() { const threshold=Number($('inventoryThreshold')?.value||5); const productOptions=products.map(p => `<option value="${escapeHTML(p.id)}">${escapeHTML(p.name)} · còn ${Number(p.stock)||0}</option>`).join(''); $('stockProduct').innerHTML=productOptions; if($('comboProduct'))$('comboProduct').innerHTML=products.filter(p=>p.id!==editingProductId&&!p.isCombo).map(p=>`<option value="${escapeHTML(p.id)}">${escapeHTML(p.name)} · còn ${Number(p.stock)||0}</option>`).join(''); renderComboItems(); const keyword=String($('adminProductSearch')?.value||'').toLocaleLowerCase('vi').trim(), category=$('adminProductCategory')?.value||'', lowOnly=$('adminProductLowStock')?.checked; const list=products.filter(p=>{const text=`${p.name} ${p.externalCode||''} ${p.barcode||''} ${p.category||''}`.toLocaleLowerCase('vi');return (!keyword||text.includes(keyword))&&(!category||p.category===category)&&(!lowOnly||Number(p.stock||0)<=threshold);}); if($('adminProductCount'))$('adminProductCount').textContent=`${list.length}/${products.length} sản phẩm`; $('adminProducts').innerHTML = list.map(p => { const stock=Number(p.stock)||0,low=stock<=threshold; const attrs=p.attributes&&typeof p.attributes==='object'?Object.entries(p.attributes).map(([k,v])=>`${escapeHTML(k)}: ${escapeHTML(v)}`).join(' · '):''; const combo=p.isCombo&&Array.isArray(p.components)?'<br>Combo: '+p.components.map(c=>{const item=products.find(x=>x.id===c.productId);return `${escapeHTML(item?.name||c.productId)} x ${Number(c.qty)}`;}).join(' · '):''; return `<div class="admin-row ${low?'low-stock-row':''}"><b>${escapeHTML(p.name)}</b>${p.isCombo?' · <span class="stock-alert">Combo</span>':''} · ${money(p.price)} · <span class="${low?'stock-alert':''}">Kho: ${stock}</span>${p.unit?` · ĐVT: ${escapeHTML(p.unit)}`:''}${p.externalCode?`<br>Mã: ${escapeHTML(p.externalCode)}`:''}${p.barcode?` · Mã vạch: ${escapeHTML(p.barcode)}`:''}${attrs?`<br>Thuộc tính: ${attrs}`:''}${combo}<br><button data-edit="${escapeHTML(p.id)}" type="button">Sửa</button><button data-delete="${escapeHTML(p.id)}" type="button">Xóa</button></div>`; }).join('') || '<p>Không có sản phẩm phù hợp bộ lọc.</p>'; }
const payableTotal=o=>Number(o.total||0)+Number(o.shippingFee||0);
const orderStatusLabel=s=>({new:'Đơn mới',confirmed:'Đã xác nhận',packing:'Đang đóng gói',shipping:'Đang giao',done:'Hoàn thành',cancelled:'Đã hủy',returned:'Hoàn hàng'}[s]||'Đơn mới');
const shippingStatusLabel=s=>({waiting_confirm:'Chờ xác nhận',confirmed:'Đã xác nhận',packed:'Đã đóng gói',handover:'Đã giao vận chuyển',delivered:'Giao thành công',returned:'Hoàn hàng'}[s]||'Chờ xác nhận');
function editProduct(id) { const p = products.find(x => x.id === id); if (!p) return; editingProductId=id; [['pName','name'],['pCategory','category'],['pPrice','price'],['pStock','stock'],['pImage','image'],['pDescription','description']].forEach(([field,key]) => $(field).value=p[key]??''); $('pImages').value=(p.images||[]).slice(1).join('\n'); $('pIsCombo').checked=!!p.isCombo; comboDraft=Array.isArray(p.components)?p.components.map(c=>({productId:c.productId,qty:Number(c.qty)||1})):[]; toggleComboBuilder(); $('pImageFile').value=''; previewProductImage(); $('productFormTitle').textContent='Sửa sản phẩm'; $('cancelProductEdit').classList.remove('hidden'); $('restoreProductDraft')?.classList.add('hidden'); $('saveProductBtn').textContent='Lưu sản phẩm'; $('pStock').value=''; $('pStock').disabled=true; setAdminTab('products'); $('pName').focus(); }
async function deleteProduct(id) { if (!confirm('Xóa sản phẩm này?')) return; try { await api(`/api/products/${encodeURIComponent(id)}`,{method:'DELETE',auth:true}); await loadProducts(); notify('Đã xóa sản phẩm.'); } catch(err) { notify(err.message,true); } }
