function collectProductDraft(){return {name:$('pName').value,category:$('pCategory').value,price:$('pPrice').value,stock:$('pStock').value,image:$('pImage').value,images:$('pImages').value,description:$('pDescription').value,isCombo:$('pIsCombo').checked,components:comboDraft,updatedAt:new Date().toISOString()};}
function saveProductDraft(){if(editingProductId)return;const d=collectProductDraft();const hasText=[d.name,d.price,d.stock,d.image,d.images,d.description].some(v=>String(v||'').trim())||d.category||d.isCombo||d.components.length;if(hasText){localStorage.setItem('productDraft',JSON.stringify(d));$('restoreProductDraft')?.classList.remove('hidden');}}
function restoreProductDraft(){try{const d=JSON.parse(localStorage.getItem('productDraft')||'null');if(!d)return notify('Chưa có nháp sản phẩm.',true);$('pName').value=d.name||'';$('pCategory').value=d.category||'';$('pPrice').value=d.price||'';$('pStock').value=d.stock||'';$('pImage').value=d.image||'';$('pImages').value=d.images||'';$('pDescription').value=d.description||'';$('pIsCombo').checked=!!d.isCombo;comboDraft=Array.isArray(d.components)?d.components:[];toggleComboBuilder();previewProductImage();setAdminTab('products');notify('Đã khôi phục nháp sản phẩm.');}catch{notify('Không đọc được nháp sản phẩm.',true);}}
function toggleComboBuilder(){const on=$('pIsCombo')?.checked;$('comboBuilder')?.classList.toggle('hidden',!on);if($('pStock'))$('pStock').disabled=!!editingProductId||!!on;renderComboItems();}
function renderComboItems(){if(!$('comboItems'))return;$('comboItems').innerHTML=comboDraft.map((c,i)=>{const p=products.find(x=>x.id===c.productId);return `<div class="admin-row"><b>${escapeHTML(p?.name||c.productId)}</b> · ${Number(c.qty)} món <button type="button" data-remove-combo="${i}">Xóa</button></div>`;}).join('')||'<p class="muted">Chưa có món con trong combo.</p>';}
function addComboItem(){const productId=$('comboProduct').value,qty=Number($('comboQty').value||1);if(!productId||!Number.isSafeInteger(qty)||qty<1)return notify('Chọn món con và số lượng hợp lệ.',true);const found=comboDraft.find(x=>x.productId===productId);if(found)found.qty+=qty;else comboDraft.push({productId,qty});$('comboQty').value='1';renderComboItems();}
const imageBytes=data=>Math.ceil(((String(data).split(',')[1]||'').length*3)/4);
const readImageFile=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Không đọc được ảnh'));reader.readAsDataURL(file);});
const loadImageData=data=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Không đọc được nội dung ảnh'));img.src=data;});
async function compressProductImage(file){
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)) throw new Error('Chọn ảnh PNG/JPG/WebP.');
  if(file.size>15*1024*1024) throw new Error('Ảnh quá lớn. Chọn ảnh tối đa 15 MB để hệ thống nén.');
  const original=await readImageFile(file);
  if(file.size<=700*1024) return {data:original,note:'Ảnh đã đủ nhẹ, giữ nguyên khi lưu.'};
  const img=await loadImageData(original), maxSide=1400, scale=Math.min(1,maxSide/Math.max(img.width,img.height));
  const canvas=document.createElement('canvas'); canvas.width=Math.max(1,Math.round(img.width*scale)); canvas.height=Math.max(1,Math.round(img.height*scale));
  canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);
  let best=canvas.toDataURL('image/webp',0.82); if(!best.startsWith('data:image/webp')) best=canvas.toDataURL('image/jpeg',0.82);
  for(const q of [0.74,0.66,0.58,0.5]){if(imageBytes(best)<=2800*1024)break;best=canvas.toDataURL(best.startsWith('data:image/webp')?'image/webp':'image/jpeg',q);}
  if(imageBytes(best)>3*1024*1024) throw new Error('Ảnh vẫn quá nặng sau khi nén. Hãy chọn ảnh nhỏ hơn hoặc crop bớt.');
  return {data:best,note:`Đã nén ảnh từ ${(file.size/1024/1024).toFixed(1)} MB xuống ${(imageBytes(best)/1024/1024).toFixed(1)} MB trước khi lưu.`};
}
async function saveProduct() {
  if(busy) return;
  if(!$('pName').value.trim() || !$('pCategory').value || $('pPrice').value==='') return notify('Nhập tên, danh mục và giá bán.',true);
  busy=true; $('saveProductBtn').disabled=true;
  try {
    const file=$('pImageFile').files[0];
    if(file) {
      const data=compressedProductImageData||((await compressProductImage(file)).data);
      const result=await api('/api/admin/uploads',{method:'POST',body:JSON.stringify({data})}); $('pImage').value=result.url; $('pImageFile').value='';
      compressedProductImageData=null; compressedProductImageName='';
    }
    const extraImages=$('pImages').value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);
    const images=[$('pImage').value.trim(),...extraImages].filter(Boolean);
    await api(editingProductId?`/api/products/${encodeURIComponent(editingProductId)}`:'/api/products',{method:editingProductId?'PUT':'POST',body:JSON.stringify({name:$('pName').value,category:$('pCategory').value,price:Number($('pPrice').value),stock:editingProductId?undefined:Number($('pStock').value||0),image:$('pImage').value,images,description:$('pDescription').value,isCombo:$('pIsCombo').checked,components:comboDraft})});
    resetProductForm(); await loadProducts(); await loadStock(); notify('Đã lưu sản phẩm.');
  } catch(err){notify(err.message,true);} finally{busy=false;$('saveProductBtn').disabled=false;}
}
