function setAdminTab(tab){document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===tab));document.querySelectorAll('[data-admin-section]').forEach(el=>el.classList.toggle('hidden',el.dataset.adminSection!==tab));}
function jumpAdminSearch(){const q=String($('adminQuickSearch')?.value||'').toLocaleLowerCase('vi').trim();if(!q)return;const card=[...document.querySelectorAll('[data-admin-section]')].find(el=>el.textContent.toLocaleLowerCase('vi').includes(q));if(!card)return notify('Không tìm thấy mục phù hợp trong admin.',true);setAdminTab(card.dataset.adminSection);setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'start'}),40);}
async function loadAdminContact(){setupAdminShell();try{const c=await api('/api/admin/contact');applyContact(c);$('contactShopName').value=c.shopName||'';$('contactTagline').value=c.tagline||'';$('contactAnnouncement').value=c.announcement||'';$('contactPhone').value=c.phone||'';$('contactEmail').value=c.email||'';$('contactZalo').value=c.zalo||'';$('contactFacebook').value=c.facebook||'';$('contactAddress').value=c.address||'';$('contactShippingNote').value=c.shippingNote||'';}catch(e){notify(e.message,true);}}
async function saveContact(){const body={shopName:$('contactShopName').value,tagline:$('contactTagline').value,announcement:$('contactAnnouncement').value,phone:$('contactPhone').value,email:$('contactEmail').value,zalo:$('contactZalo').value,facebook:$('contactFacebook').value,address:$('contactAddress').value,shippingNote:$('contactShippingNote').value};$('saveContactBtn').disabled=true;try{applyContact(await api('/api/admin/contact',{method:'PUT',body:JSON.stringify(body)}));notify('Đã lưu thông tin liên hệ.');}catch(e){notify(e.message,true);}finally{$('saveContactBtn').disabled=false;}}
async function loadAdminSiteTheme(){setupAdminShell();try{const [site,theme,tpl,policies,inventory]=await Promise.all([api('/api/admin/site'),api('/api/admin/theme'),api('/api/admin/import-template'),api('/api/admin/policies'),api('/api/admin/inventory')]);applySite(site);applyTheme(theme);applyPolicies(policies);importTemplate=tpl||{map:{},attributeColumns:[]};$('siteHeroEyebrow').value=site.heroEyebrow||'';$('siteHeroTitle').value=site.heroTitle||'';$('siteHeroHighlight').value=site.heroHighlight||'';$('siteHeroCta').value=site.heroCta||'';$('siteHeroText').value=site.heroText||'';$('siteHeroNote').value=site.heroNote||'';$('siteHeroImage').value=site.heroImage||'';$('siteCategoryTitle').value=site.categoryTitle||'';$('siteProductsTitle').value=site.productsTitle||'';$('siteBestTitle').value=site.bestTitle||'';$('siteService1Title').value=site.service1Title||'';$('siteService1Text').value=site.service1Text||'';$('siteService2Title').value=site.service2Title||'';$('siteService2Text').value=site.service2Text||'';$('siteService3Title').value=site.service3Title||'';$('siteService3Text').value=site.service3Text||'';$('themeAccent').value=theme.accent||'#b45043';$('themeAccentDark').value=theme.accentDark||'#913e35';$('themeCream').value=theme.cream||'#fcf8f5';$('themeInk').value=theme.ink||'#28312e';$('themeLine').value=theme.line||'#eee6e0';$('themeCardRadius').value=theme.cardRadius??11;$('themeButtonRadius').value=theme.buttonRadius??8;$('themeEffects').checked=theme.effects!==false;$('policyShipping').value=policies.shipping||'';$('policyReturns').value=policies.returns||'';$('policyPayment').value=policies.payment||'';$('policyPrivacy').value=policies.privacy||'';$('inventoryThreshold').value=inventory.lowStockThreshold??5;renderAdminProducts();}catch(e){notify(e.message,true);}}
async function saveSite(){const body={heroEyebrow:$('siteHeroEyebrow').value,heroTitle:$('siteHeroTitle').value,heroHighlight:$('siteHeroHighlight').value,heroCta:$('siteHeroCta').value,heroText:$('siteHeroText').value,heroNote:$('siteHeroNote').value,heroImage:$('siteHeroImage').value,categoryTitle:$('siteCategoryTitle').value,productsTitle:$('siteProductsTitle').value,bestTitle:$('siteBestTitle').value,service1Title:$('siteService1Title').value,service1Text:$('siteService1Text').value,service2Title:$('siteService2Title').value,service2Text:$('siteService2Text').value,service3Title:$('siteService3Title').value,service3Text:$('siteService3Text').value};$('saveSiteBtn').disabled=true;try{applySite(await api('/api/admin/site',{method:'PUT',body:JSON.stringify(body)}));notify('Đã lưu trang chủ.');}catch(e){notify(e.message,true);}finally{$('saveSiteBtn').disabled=false;}}
async function saveTheme(){const body={accent:$('themeAccent').value,accentDark:$('themeAccentDark').value,cream:$('themeCream').value,ink:$('themeInk').value,line:$('themeLine').value,cardRadius:Number($('themeCardRadius').value),buttonRadius:Number($('themeButtonRadius').value),effects:$('themeEffects').checked};$('saveThemeBtn').disabled=true;try{applyTheme(await api('/api/admin/theme',{method:'PUT',body:JSON.stringify(body)}));notify('Đã lưu giao diện.');}catch(e){notify(e.message,true);}finally{$('saveThemeBtn').disabled=false;}}
async function savePolicies(){const body={shipping:$('policyShipping').value,returns:$('policyReturns').value,payment:$('policyPayment').value,privacy:$('policyPrivacy').value};$('savePoliciesBtn').disabled=true;try{applyPolicies(await api('/api/admin/policies',{method:'PUT',body:JSON.stringify(body)}));notify('Đã lưu chính sách.');}catch(e){notify(e.message,true);}finally{$('savePoliciesBtn').disabled=false;}}
async function saveInventory(){try{const saved=await api('/api/admin/inventory',{method:'PUT',body:JSON.stringify({lowStockThreshold:Number($('inventoryThreshold').value||0)})});$('inventoryThreshold').value=saved.lowStockThreshold;renderAdminProducts();await loadDashboard();notify('Đã lưu ngưỡng tồn kho.');}catch(e){notify(e.message,true);}}
async function loadDashboard(){try{const d=await api('/api/admin/dashboard');if($('inventoryThreshold')&&!$('inventoryThreshold').value)$('inventoryThreshold').value=d.lowStockThreshold;$('adminDashboard').innerHTML=`<div class="metric"><span>Doanh thu hôm nay</span><b>${money(d.revenueToday)}</b></div><div class="metric"><span>Doanh thu tháng</span><b>${money(d.revenueMonth)}</b></div><div class="metric"><span>Đơn mới</span><b>${Number(d.newOrders)}</b></div><div class="metric"><span>Chưa thanh toán</span><b>${Number(d.unpaidOrders)}</b></div>`;$('dashboardLowStock').innerHTML=(d.lowStock||[]).map(p=>`<div class="admin-row low-stock-row"><b>${escapeHTML(p.name)}</b> · còn ${Number(p.stock||0)}${p.externalCode?` · ${escapeHTML(p.externalCode)}`:''}</div>`).join('')||'<p>Chưa có sản phẩm dưới ngưỡng cảnh báo.</p>';}catch(e){notify(e.message,true);}}
async function loadReports(){try{const r=await api('/api/admin/reports');$('salesReport').innerHTML=`<div class="metric"><span>Tổng doanh thu</span><b>${money(r.revenue)}</b></div><div class="metric"><span>Tiền hàng</span><b>${money(r.goodsRevenue)}</b></div><div class="metric"><span>Phí ship</span><b>${money(r.shippingRevenue)}</b></div><div class="metric"><span>Giá trị đơn TB</span><b>${money(r.averageOrder)}</b></div><div class="metric"><span>Đơn đã thanh toán</span><b>${Number(r.paidOrders)}</b></div><div class="metric"><span>Đơn hủy</span><b>${Number(r.cancelled)}</b></div>`;$('topProductsReport').innerHTML=(r.topProducts||[]).map(p=>`<div class="admin-row"><b>${escapeHTML(p.name)}</b> · bán ${Number(p.qty)} · ${money(p.revenue)}</div>`).join('')||'<p>Chưa có dữ liệu bán hàng.</p>';$('slowProductsReport').innerHTML=(r.slowProducts||[]).map(p=>`<div class="admin-row"><b>${escapeHTML(p.name)}</b> · tồn ${Number(p.stock||0)}</div>`).join('')||'<p>Chưa có hàng chậm bán.</p>';}catch(e){notify(e.message,true);}}
async function loadAuditLogs(){try{const logs=await api('/api/admin/audit-logs');$('auditLogs').innerHTML=logs.map(l=>`<div class="admin-row"><b>${escapeHTML(l.action)}</b> · ${escapeHTML(l.actorEmail||'admin')}<br>${escapeHTML(l.target||'')} ${l.detail?`· ${escapeHTML(l.detail)}`:''}<br><small>${new Date(l.createdAt).toLocaleString('vi-VN')}</small></div>`).join('')||'<p>Chưa có thao tác nào được ghi lại.</p>';}catch(e){notify(e.message,true);}}
async function saveCurrentImportTemplate(){if(!importSession)return notify('Hãy đọc một file Excel trước, chọn mapping cột rồi bấm lưu mẫu.',true);try{const map={name:Number($('mapName').value),category:Number($('mapCategory').value),price:Number($('mapPrice').value),stock:Number($('mapStock').value),unit:Number($('mapUnit').value),code:Number($('mapCode').value),barcode:Number($('mapBarcode').value),cost:Number($('mapCost').value),image:Number($('mapImage').value),description:Number($('mapDescription').value)};const attributeColumns=[...$('attributeColumns').querySelectorAll('input:checked')].map(x=>Number(x.value));importTemplate=await api('/api/admin/import-template',{method:'PUT',body:JSON.stringify({map,attributeColumns})});notify('Đã lưu mẫu nhập Excel. File sau sẽ tự gợi ý mapping này.');}catch(e){notify(e.message,true);}}
async function downloadBackup(){try{const data=await api('/api/admin/backup');const blob=new Blob([JSON.stringify(data.backup,null,2)],{type:'application/json;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=data.filename;document.body.appendChild(a);a.click();URL.revokeObjectURL(a.href);a.remove();notify('Đã tải backup dữ liệu.');}catch(e){notify(e.message,true);}}
async function loadAdminPromotions(){setupAdminShell();try{const data=await api('/api/admin/promotions');promotions=data.promotions||[];holidayPresets=data.holidays||[];$('promoHoliday').innerHTML='<option value="">Tự đặt ngày</option>'+holidayPresets.map(h=>`<option value="${escapeHTML(h.id)}">${escapeHTML(h.name)} (${escapeHTML(h.date)})</option>`).join('');renderPromoList();renderCart();renderProducts();}catch(e){notify(e.message,true);}}
function renderPromoList(){if(!$('promoList'))return;$('promoList').innerHTML=promotions.map(p=>`<div class="admin-row"><b>${escapeHTML(p.name)}</b> · ${(p.dayType==='holiday'||p.holiday)?'Ngày lễ':'Ngày thường'} · ${p.enabled?'Đang bật':'Đang tắt'} · ${escapeHTML(p.starts||'')} đến ${escapeHTML(p.ends||'')}<br>${p.type==='amount'?money(p.value):`${Number(p.value)}%`} ${p.code?`· Mã ${escapeHTML(p.code)}`:'· Tự áp dụng'}${p.minTotal?` · Ưu tiên tiền từ ${money(p.minTotal)}`:''}${p.minItems?` · Từ ${Number(p.minItems)} món`:''}<br><button data-toggle-promo="${escapeHTML(p.id)}" type="button">${p.enabled?'Tắt':'Bật'}</button><button data-delete-promo="${escapeHTML(p.id)}" type="button">Xóa</button></div>`).join('')||'<p>Chưa có ưu đãi.</p>';}
function fillHolidayPromo(){const h=holidayPresets.find(x=>x.id===$('promoHoliday').value);if(!h)return;const year=new Date().getFullYear();$('promoDayType').value='holiday';$('promoName').value=h.name;$('promoStart').value=`${year}-${h.date}`;$('promoEnd').value=`${year}-${h.date}`;}
