async function addPromotion(){try{const p={id:crypto.randomUUID(),enabled:$('promoEnabled').checked,dayType:$('promoDayType').value,name:$('promoName').value,holiday:$('promoHoliday').value,starts:$('promoStart').value,ends:$('promoEnd').value,type:$('promoType').value,value:Number($('promoValue').value||0),minItems:Number($('promoMinItems').value||0),minTotal:Number($('promoMinTotal').value||0),code:$('promoCode').value,note:$('promoNote').value};if(!p.name||!p.starts||!p.ends||!p.value)return notify('Nhập tên, ngày và giá trị ưu đãi.',true);promotions.unshift(p);await savePromotions();['promoName','promoStart','promoEnd','promoValue','promoMinItems','promoMinTotal','promoCode','promoNote'].forEach(id=>$(id).value='');$('promoDayType').value='normal';$('promoHoliday').value='';notify('Đã thêm ưu đãi.');}catch(e){notify(e.message,true);}}
