function printOrder(id){const o=adminOrdersCache.find(x=>x.id===id);if(!o)return;const html=`<!doctype html><html><head><meta charset="utf-8"><title>${escapeHTML(o.orderCode)}</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#222}h1{font-size:22px}.box{border:1px solid #ddd;padding:14px;margin:12px 0}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ddd;padding:8px;text-align:left}.total{text-align:right;font-size:18px;font-weight:700}@media print{button{display:none}}</style></head><body><button onclick="print()">In phiếu</button><h1>Phiếu đơn hàng ${escapeHTML(o.orderCode)}</h1><div class="box"><b>Khách:</b> ${escapeHTML(o.customer?.name)}<br><b>SĐT:</b> ${escapeHTML(o.customer?.phone)}<br><b>Địa chỉ:</b> ${escapeHTML(o.customer?.address)}<br><b>Email:</b> ${escapeHTML(o.userEmail||'')}</div><table><thead><tr><th>Sản phẩm</th><th>SL</th><th>Đơn giá</th><th>Thành tiền</th></tr></thead><tbody>${(o.items||[]).map(i=>`<tr><td>${escapeHTML(i.name)}</td><td>${Number(i.qty)}</td><td>${money(i.price)}</td><td>${money(Number(i.qty)*Number(i.price))}</td></tr>`).join('')}</tbody></table><p class="total">Tiền hàng: ${money(o.total)}<br>Phí ship: ${money(o.shippingFee||0)}<br>Tổng cần thu: ${money(payableTotal(o))}</p><div class="box"><b>Thanh toán:</b> ${paymentLabel(o)}<br><b>Trạng thái:</b> ${orderStatusLabel(o.orderStatus)} / ${shippingStatusLabel(o.shippingStatus)}<br><b>Ghi chú nội bộ:</b><br>${escapeHTML(o.internalNote||'')}</div></body></html>`;const w=window.open('','_blank','width=800,height=900');if(!w)return notify('Trình duyệt đang chặn cửa sổ in.',true);w.document.write(html);w.document.close();w.focus();}
