const mapHints={mapName:['tên hàng','tên sản phẩm','name'],mapCategory:['nhóm hàng','danh mục','category'],mapPrice:['giá bán','baseprice','price'],mapStock:['tồn kho','onhand','stock'],mapUnit:['đvt','đơn vị','unit'],mapCode:['mã hàng','sku','code'],mapBarcode:['mã vạch','barcode'],mapCost:['giá vốn','cost'],mapImage:['ảnh','image','hình'],mapDescription:['mô tả','ghi chú','description']};
function guessColumn(headers,id){const hints=mapHints[id]||[];return headers.findIndex(h=>hints.some(x=>String(h).toLocaleLowerCase('vi').includes(x)));}
function renderImportMapper(data){importSession=data;$('importMapper').classList.remove('hidden');$('importSummary').textContent=`Đã đọc ${data.total} dòng, ${data.headers.length} cột. Hãy gắn cột trước khi nhập.`;const options='<option value="-1">Không nhập</option>'+data.headers.map((h,i)=>`<option value="${i}">${escapeHTML(h)}</option>`).join('');const saved=importTemplate?.map||{};for(const id of mapIds){$(id).innerHTML=options;const key=id.replace(/^map/,'').replace(/^./,c=>c.toLowerCase());const savedValue=Number(saved[key]);$(id).value=String(Number.isInteger(savedValue)&&savedValue<data.headers.length?savedValue:guessColumn(data.headers,id));}const used=new Set(mapIds.map(id=>Number($(id).value)).filter(i=>i>=0));const savedAttrs=new Set((importTemplate?.attributeColumns||[]).filter(i=>i<data.headers.length));$('attributeColumns').innerHTML=data.headers.map((h,i)=>`<label class="check-label"><input type="checkbox" value="${i}" ${(savedAttrs.size?savedAttrs.has(i):!used.has(i))?'checked':''} /> ${escapeHTML(h)}</label>`).join('');$('importPreview').innerHTML=`<table><thead><tr>${data.headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${data.preview.map(r=>`<tr>${data.headers.map((_,i)=>`<td>${escapeHTML(r[i]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
async function previewImport(){const file=$('importFile').files[0];if(!file)return notify('Chọn file Excel hoặc CSV trước.',true);$('previewImportBtn').disabled=true;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Không đọc được file'));r.readAsDataURL(file);});renderImportMapper(await api('/api/admin/import/preview',{method:'POST',body:JSON.stringify({data})}));notify('Đã đọc file. Hãy kiểm tra mapping cột.');}catch(e){notify(e.message,true);}finally{$('previewImportBtn').disabled=false;}}
