function previewProductImage(){
 if(selectedImagePreview) URL.revokeObjectURL(selectedImagePreview); selectedImagePreview=null; compressedProductImageData=null; compressedProductImageName='';
 const file=$('pImageFile').files[0];const preview=$('pImagePreview'),note=$('imageOptimizeNote');
 if(file){
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024){$('pImageFile').value='';if(note)note.textContent='PNG, JPG, WebP. Ảnh lớn sẽ được tự nén trước khi lưu.';notify('Chọn ảnh PNG/JPG/WebP tối đa 15 MB.',true);return previewProductImage();}
  selectedImagePreview=URL.createObjectURL(file);preview.src=selectedImagePreview;preview.classList.remove('hidden');
  if(note)note.textContent=file.size>700*1024?'Đang chuẩn bị nén ảnh trước khi lưu...':'Ảnh đã đủ nhẹ, giữ nguyên khi lưu.';
  compressProductImage(file).then(result=>{compressedProductImageData=result.data;compressedProductImageName=file.name;if(note)note.textContent=result.note;}).catch(err=>{if(note)note.textContent='Không nén được ảnh này. Hãy chọn ảnh khác.';notify(err.message,true);});
 }
 else{if(note)note.textContent='PNG, JPG, WebP. Ảnh lớn sẽ được tự nén trước khi lưu.';const url=safeImage($('pImage').value);preview.classList.toggle('hidden',!$('pImage').value||!url);if(url)preview.src=new URL($('pImage').value,location.href).href;else preview.removeAttribute('src');}
}
