function renderPayment(o){
 const cancelled=o.orderStatus==='cancelled'; const needsPayment=o.paymentStatus==='unpaid'&&!cancelled;
 const due=payableTotal(o); const remaining=Math.max(0,due-Number(o.receivedAmount||0));const bank=o.bank;
 let qr=bank?.qrUrl||'';if(qr&&Number(o.receivedAmount)>0){const url=new URL(qr);url.searchParams.set('amount',String(remaining));qr=url.href;}
 const payLater=needsPayment?'<button class="secondary-btn full" data-pay-later type="button">Thanh toán sau</button>':'';
 $('qrBox').innerHTML=`<span class="eyebrow">ĐƠN HÀNG CỦA BẠN</span><h2>${escapeHTML(o.orderCode)}</h2><span class="order-status ${o.paymentStatus==='paid'?'paid':''}">${cancelled?'Đơn đã hủy':paymentLabel(o)}</span><span class="order-status">${shippingStatusLabel(o.shippingStatus)}</span><div class="payment-detail"><p>Tạm tính hàng: <b>${money(o.subtotal||o.total)}</b></p>${o.discount?`<p>Ưu đãi ${escapeHTML(o.promotion?.name||'')}: <b>-${money(o.discount)}</b></p>`:''}<p>Tổng tiền hàng: <b>${money(o.total)}</b></p><p>Phí ship: <b>${Number(o.shippingFee||0)?money(o.shippingFee):'Shop sẽ báo riêng'}</b></p><p>Tổng cần thu: <b>${money(due)}</b></p><p class="ship-note in-box">${escapeHTML(contactSettings.shippingNote||'Chưa bao gồm phí ship. Shop sẽ tính phí vận chuyển qua SPX Express và báo riêng.')}</p><p>${escapeHTML(o.customer.name)} · ${escapeHTML(o.customer.phone)}</p><p>${escapeHTML(o.customer.address)}</p>${o.receivedAmount?`<p>Đã nhận: ${money(o.receivedAmount)} · Còn thiếu: ${money(remaining)}</p>`:''}</div>${needsPayment&&o.paymentMethod==='bank_transfer'&&bank?`<p>Quét QR hoặc chuyển khoản đúng nội dung mã đơn. Nếu muốn chốt đơn trước, bạn có thể bấm thanh toán sau và mở lại QR trong Đơn hàng của tôi.</p><p>Số tài khoản: <b>${escapeHTML(bank.accountNo)}</b> · ${escapeHTML(bank.accountName)}</p><p>Nội dung: <b>${escapeHTML(bank.transferContent)}</b></p><img class="qr-image" src="${safeImage(qr)}" alt="QR thanh toán đơn hàng" /><p>Hệ thống sẽ kiểm tra khi shop nhận được xác nhận chuyển khoản.</p>`:needsPayment?'<p>Đơn đang chờ thanh toán chuyển khoản.</p>':''}<button class="primary-btn full" data-refresh-payment type="button">Tôi đã chuyển khoản - kiểm tra</button>${payLater}<p id="paymentCheckNote" class="muted">Đã cập nhật lúc ${new Date().toLocaleTimeString('vi-VN')}</p><button class="secondary-btn full" data-close type="button">Đóng</button>`;
}
async function refreshPayment(quiet=false){if(!viewedOrderId)return;if(!currentUser){if(!quiet)notify('Đơn đã gửi cho shop. Khách chưa đăng nhập sẽ được shop xác nhận thanh toán thủ công.',false);return;}const id=viewedOrderId;try{const o=await api('/api/orders/'+encodeURIComponent(id));if(id===viewedOrderId && !$('checkoutModal').classList.contains('hidden'))renderPayment(o);}catch(e){if(!quiet)notify(e.message,true);else if($('paymentCheckNote'))$('paymentCheckNote').textContent='Chưa kết nối được máy chủ để cập nhật trạng thái.';}}
async function viewOrder(id){try{const o=await api('/api/orders/'+encodeURIComponent(id));openModal('checkoutModal');viewedOrderId=id;$('checkoutForm').classList.add('hidden');$('qrBox').classList.remove('hidden');renderPayment(o);}catch(e){notify(e.message,true);}}
async function loadMyOrders(quiet=false){const user=currentUser;try{const orders=await api('/api/my-orders');if(user!==currentUser)return;$('myOrdersList').innerHTML=orders.map(o=>`<div class="order-row"><h3>${escapeHTML(o.orderCode)}</h3><span class="order-status ${o.paymentStatus==='paid'?'paid':''}">${o.orderStatus==='cancelled'?'Đã hủy':paymentLabel(o)}</span><span class="order-status">${shippingStatusLabel(o.shippingStatus)}</span><p>${(o.items||[]).map(i=>`${escapeHTML(i.name)} × ${Number(i.qty)}`).join('<br>')}</p><b>${money(payableTotal(o))}</b><p class="ship-note">Tiền hàng ${money(o.total)} · Ship ${Number(o.shippingFee||0)?money(o.shippingFee):'shop báo riêng'}</p><div class="order-actions"><button class="secondary-btn" type="button" data-view-order="${escapeHTML(o.id)}">Xem QR / thanh toán</button></div></div>`).join('')||'<p>Bạn chưa có đơn hàng.</p>';}catch(e){if(!quiet)notify(e.message,true);}}
$('myOrdersBtn').onclick=()=>{openModal('myOrdersModal');loadMyOrders();};
$('refreshMyOrders').onclick=()=>loadMyOrders();
document.addEventListener('click',e=>{const order=e.target.closest('[data-view-order]');if(order)viewOrder(order.dataset.viewOrder);if(e.target.closest('[data-refresh-payment]'))refreshPayment();if(e.target.closest('[data-pay-later]')){closeLayers();notify('Đơn đã lưu. Bạn có thể mở Đơn hàng của tôi để thanh toán sau.');}});
function showIntegrationStatus(config){$('integrationStatus').textContent=config.enabled?`Đã bật nhận thông báo. ${config.lastReceivedAt?'Lần nhận gần nhất: '+new Date(config.lastReceivedAt).toLocaleString('vi-VN'):'Chưa nhận được thông báo giao dịch. Hãy hoàn tất cấu hình trên SePay.'}`:'Đang tắt xác nhận tự động; admin vẫn có thể xác nhận thủ công.';$('sepaySecret').placeholder=config.secretConfigured?'Đã lưu key; để trống để giữ nguyên':'Nhập API Key webhook từ 32 ký tự';}
$('saveIntegrationBtn').onclick=async()=>{ $('saveIntegrationBtn').disabled=true;try{const config=await api('/api/admin/payment-integration',{method:'PUT',body:JSON.stringify({enabled:$('autoPaymentEnabled').checked,gateway:$('sepayGateway').value,secret:$('sepaySecret').value})});$('sepaySecret').value='';showIntegrationStatus(config);notify('Đã lưu cấu hình nhận giao dịch.');}catch(e){notify(e.message,true);}finally{$('saveIntegrationBtn').disabled=false;}};
async function loadTransactions(quiet=false){try{const events=await api('/api/admin/bank-transactions');$('bankTransactions').innerHTML=events.map(t=>`<div class="admin-row"><b>${money(t.amount)}</b> · ${escapeHTML(t.gateway)} · ${escapeHTML(t.orderCode || 'Chưa khớp đơn')}<br>${escapeHTML(t.note)}<br><small>${escapeHTML(t.transactionDate)} · ${escapeHTML(t.referenceCode || t.id)}</small></div>`).join('')||'<p>Chưa nhận được giao dịch từ ngân hàng.</p>';}catch(e){if(!quiet)notify(e.message,true);}}
setInterval(async()=>{
 if(!currentUser||document.hidden||polling)return;polling=true;
 try{
  if(!$('checkoutModal').classList.contains('hidden')&&!$('qrBox').classList.contains('hidden'))await refreshPayment(true);
  if(!$('myOrdersModal').classList.contains('hidden'))await loadMyOrders(true);
 if(!$('adminPanel').classList.contains('hidden')&&!$('adminOrders').contains(document.activeElement)){await loadOrders(true);await loadTransactions(true);await loadAuditLogs();}
 }finally{polling=false;}
},10000);



